const CATEGORY_TABS_SCRIPT = '<scr'+'ipt id="_wsCategoryTabs">(function(){function move(ind,tab){if(!ind||!tab)return;ind.style.left=tab.offsetLeft+"px";ind.style.width=tab.offsetWidth+"px";}function init(tabs){if(tabs.getAttribute("data-wsct"))return;tabs.setAttribute("data-wsct","1");var ind=tabs.querySelector(".wsp-tab-ind");var btns=tabs.querySelectorAll(".wsp-tab");var grid=(tabs.parentNode&&tabs.parentNode.querySelector(".wsp-grid"))||document.querySelector(".wsp-grid");function activate(btn){for(var i=0;i<btns.length;i++)btns[i].classList.remove("wsp-tab-on");btn.classList.add("wsp-tab-on");move(ind,btn);var cat=btn.getAttribute("data-cat")||"";if(grid){var cards=grid.querySelectorAll(".wsp-card");for(var j=0;j<cards.length;j++){var cc=cards[j].getAttribute("data-category")||"";cards[j].style.display=(!cat||cc===cat)?"":"none";}}}for(var b=0;b<btns.length;b++){btns[b].addEventListener("click",function(){activate(this);});}var on=tabs.querySelector(".wsp-tab-on")||btns[0];if(on)move(ind,on);}function run(){var t=document.querySelectorAll(".wsp-tabs");for(var i=0;i<t.length;i++)init(t[i]);}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",run);}else{run();}setTimeout(run,400);setTimeout(run,1200);window.addEventListener("resize",function(){var t=document.querySelectorAll(".wsp-tabs");for(var i=0;i<t.length;i++){var ind=t[i].querySelector(".wsp-tab-ind");var on=t[i].querySelector(".wsp-tab-on");if(ind&&on){ind.style.left=on.offsetLeft+"px";ind.style.width=on.offsetWidth+"px";}}});})();</scr'+'ipt>';
const HEADER_FIX_SCRIPT = '<scr'+'ipt id="_wsHeaderFix">(function(){try{var s=document.createElement("style");s.textContent="header>nav,header .site-nav,header>.container{display:flex!important;align-items:center!important;flex-wrap:wrap!important;gap:14px 26px!important;width:100%}"+"@media(min-width:900px){header>nav,header .site-nav,header>.container{justify-content:space-between!important;flex-wrap:nowrap!important}}"+"header>nav>*,header .site-nav>*{flex:0 1 auto;min-width:0}"+"header>nav ul,header .site-nav ul{display:flex!important;align-items:center;flex-wrap:wrap;gap:12px 22px!important;list-style:none;margin:0;padding:0}";document.head.appendChild(s);}catch(e){}})();</scr'+'ipt>';
const CSS_STRIP_SCRIPT = '<scr'+'ipt id="_wsCssStrip">(function(){function count(s,ch){var n=0,i=0;while((i=s.indexOf(ch,i))>-1){n++;i++;}return n;}function looksLikeCss(t){if(!t||t.length<40)return false;var open=count(t,"{"),close=count(t,"}");if(open<2||close<2)return false;var semi=count(t,";");if(t.indexOf("*/")>-1||t.indexOf("@media")>-1||t.indexOf("@keyframes")>-1)return true;return t.indexOf(":")>-1&&semi>=3;}function inCode(el){while(el){var g=el.tagName;if(g==="STYLE"||g==="SCRIPT"||g==="PRE"||g==="CODE"||g==="TEXTAREA")return true;el=el.parentElement;}return false;}function strip(){try{if(!document.body)return;var w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,null);var kill=[],node;while(node=w.nextNode()){var t=node.nodeValue||"";if(!looksLikeCss(t))continue;if(inCode(node.parentElement))continue;kill.push(node);}for(var i=0;i<kill.length;i++){var n=kill[i];var par=n.parentElement;if(n.parentNode)n.parentNode.removeChild(n);if(par&&par!==document.body&&(par.textContent||"").trim()===""&&par.children.length===0&&par.parentNode)par.parentNode.removeChild(par);}}catch(e){}}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",strip);}else{strip();}setTimeout(strip,300);setTimeout(strip,1000);})();</scr'+'ipt>';
function withReveal(html){
  if(!html||html.indexOf('_wsReveal')>-1)return html;
  var bi=html.lastIndexOf('</body>');
  var _both = NAV_CONTRAST_SCRIPT + CTA_EDGE_SCRIPT + NAV_DEDUPE_SCRIPT + TEXT_CONTRAST_SCRIPT + PRODUCT_MODAL_SCRIPT + CATEGORY_TABS_SCRIPT + HEADER_FIX_SCRIPT + CSS_STRIP_SCRIPT + REVEAL_SCRIPT;
  return bi>-1?html.slice(0,bi)+_both+html.slice(bi):html+_both;
}

