function priceToCents(v){
  if (v == null) return 0;
  var str = String(v).replace(/[^0-9.]/g, '');
  if (!str) return 0;
  var n = parseFloat(str);
  if (!isFinite(n) || n <= 0) return 0;
  return Math.round(n * 100);
}
